"use client";

import {
  Bookmark,
  Brain,
  Lightbulb,
  MessageSquare,
  Search,
  StickyNote,
  Zap,
} from "lucide-react";
import { cn } from "@/lib/utils";

export type NavItem = "chat" | "notes" | "saved" | "recall";

type AppSidebarProps = {
  activeNav: NavItem;
  onNavChange: (nav: NavItem) => void;
  searchQuery: string;
  onSearchChange: (query: string) => void;
  memoryCount: number;
};

const navItems: { id: NavItem; label: string; icon: typeof MessageSquare }[] = [
  { id: "chat", label: "Chat", icon: MessageSquare },
  { id: "notes", label: "Notes", icon: StickyNote },
  { id: "saved", label: "Saved", icon: Bookmark },
  { id: "recall", label: "Recall", icon: Zap },
];

export function AppSidebar({
  activeNav,
  onNavChange,
  searchQuery,
  onSearchChange,
  memoryCount,
}: AppSidebarProps) {
  return (
    <aside className="flex h-full w-full flex-col border-r border-sidebar-border bg-sidebar px-4 py-5 sm:w-56 sm:min-w-56 sm:max-w-56 lg:w-60 lg:min-w-60 lg:max-w-60">
      <div className="mb-5 flex items-center gap-2.5">
        <div
          className="flex size-9 shrink-0 items-center justify-center rounded-xl bg-primary text-primary-foreground shadow-sm"
          aria-hidden
        >
          <Lightbulb className="size-5" />
        </div>
        <span className="text-lg font-bold tracking-tight text-primary">
          Second Brain
        </span>
      </div>

      <div className="mb-6 rounded-2xl bg-cream-dark p-2.5">
        <div className="relative flex items-center gap-2 rounded-xl bg-chat-input px-3 py-2.5">
          <Search className="size-4 shrink-0 text-chat-input-foreground/70" />
          <input
            type="search"
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder="Search memories."
            className="min-w-0 flex-1 bg-transparent text-sm text-primary placeholder:text-primary/60 focus:outline-none"
            aria-label="Search memories"
          />
        </div>
      </div>

      <nav aria-label="Navigation">
        <p className="mb-2 px-2 text-[10px] font-semibold tracking-widest text-muted-foreground">
          NAVIGATION
        </p>
        <ul className="space-y-1">
          {navItems.map(({ id, label, icon: Icon }) => {
            const isActive = activeNav === id;
            return (
              <li key={id}>
                <button
                  type="button"
                  onClick={() => onNavChange(id)}
                  className={cn(
                    "flex w-full items-center gap-3 rounded-2xl px-3 py-2.5 text-sm font-medium transition-colors",
                    isActive
                      ? "bg-primary text-primary-foreground shadow-sm"
                      : "text-primary hover:bg-cream-dark",
                  )}
                >
                  <Icon className="size-4 shrink-0" />
                  {label}
                </button>
              </li>
            );
          })}
        </ul>
      </nav>

      <div className="mt-auto space-y-3 pt-6">
        <div className="rounded-2xl border border-border/60 bg-card px-3 py-3 shadow-sm">
          <div className="flex items-center gap-2 text-primary">
            <Brain className="size-4 shrink-0" />
            <span className="text-[10px] font-semibold tracking-widest">
              MEMORY
            </span>
          </div>
          <p className="mt-1 text-sm text-muted-foreground">
            {memoryCount} saved {memoryCount === 1 ? "note" : "notes"}
          </p>
        </div>

        <div className="flex items-center gap-3 rounded-2xl border border-border/60 bg-card px-3 py-2.5">
          <div
            className="flex size-9 shrink-0 items-center justify-center rounded-full bg-primary text-xs font-semibold text-primary-foreground"
            aria-hidden
          >
            You
          </div>
          <span className="text-sm font-medium text-foreground">User</span>
        </div>
      </div>
    </aside>
  );
}
